import { discoveries } from "@/content/catalog";
import { getBySlug } from "@/lib/discoveries";
import type { AskResult } from "./types";

/**
 * LLM seam. When ANTHROPIC_API_KEY is set, answers are generated by Claude;
 * otherwise the app falls back to the local rule-based engine (engine.ts).
 *
 * ── To enable AI answers later ────────────────────────────────────────────
 *   1. Add to your environment (e.g. .env.local, see .env.example):
 *        ANTHROPIC_API_KEY=sk-ant-...
 *        ANTHROPIC_MODEL=claude-sonnet-5      # optional, this is the default
 *   2. Restart the server. That's it — /api/ask starts using Claude and the
 *      UI badge switches from "local" to "AI".
 * The key is read server-side only and never shipped to the browser.
 */

const ANTHROPIC_API_URL = "https://api.anthropic.com/v1/messages";
const DEFAULT_MODEL = "claude-sonnet-5";

export function isLlmConfigured(): boolean {
  return Boolean(process.env.ANTHROPIC_API_KEY);
}

/** Compact catalog handed to the model so it can reason over real data. */
function catalogForPrompt() {
  return discoveries.map((d) => ({
    slug: d.slug,
    title: d.title,
    category: d.categorySlug,
    subtopic: d.subtopic,
    year: d.year,
    date: d.dateDiscovered,
    country: d.location.country,
    organization: d.discoveringOrg,
    depthMeters: d.location.depthMeters ?? null,
    scientificName: d.scientificName ?? null,
    tags: d.tags,
    summary: d.summary,
  }));
}

interface ClaudeAnswerShape {
  interpretation: string;
  answer: string;
  slugs: string[];
}

/**
 * Ask Claude to interpret the question against the catalog and return the
 * matching discovery slugs plus a natural-language answer. Throws on any
 * failure so the caller can fall back to the local engine.
 */
export async function answerWithClaude(query: string): Promise<AskResult> {
  const apiKey = process.env.ANTHROPIC_API_KEY;
  if (!apiKey) throw new Error("ANTHROPIC_API_KEY is not set");

  const system =
    "You are the search assistant for Beyond Signal, a directory of scientific " +
    "discoveries. You are given a JSON catalog of discoveries and a user question. " +
    "Answer ONLY from the catalog. Respond with a single JSON object and nothing " +
    'else, in the shape: {"interpretation": string, "answer": string, "slugs": ' +
    "string[]}. `interpretation` restates how you read the question. `answer` is a " +
    "concise, friendly one- or two-sentence reply. `slugs` lists the slugs of the " +
    "matching discoveries, most relevant first (empty if none match). Never invent " +
    "slugs that are not in the catalog.";

  // Abort a slow upstream so the request can't hang; the caller falls back to
  // the local engine on the resulting error.
  const controller = new AbortController();
  const timeout = setTimeout(() => controller.abort(), 15_000);
  let res: Response;
  try {
    res = await fetch(ANTHROPIC_API_URL, {
      method: "POST",
      headers: {
        "content-type": "application/json",
        "x-api-key": apiKey,
        "anthropic-version": "2023-06-01",
      },
      body: JSON.stringify({
        model: process.env.ANTHROPIC_MODEL || DEFAULT_MODEL,
        max_tokens: 1024,
        system,
        messages: [
          {
            role: "user",
            content: `Catalog:\n${JSON.stringify(catalogForPrompt())}\n\nQuestion: ${query}`,
          },
        ],
      }),
      signal: controller.signal,
    });
  } finally {
    clearTimeout(timeout);
  }

  if (!res.ok) {
    throw new Error(`Anthropic API error: ${res.status} ${await res.text()}`);
  }

  const data = (await res.json()) as {
    content?: { type: string; text?: string }[];
  };
  const text = data.content?.find((c) => c.type === "text")?.text ?? "";
  const start = text.indexOf("{");
  const end = text.lastIndexOf("}");
  if (start === -1 || end === -1) {
    throw new Error("Claude response did not contain a JSON object.");
  }
  const parsed = JSON.parse(text.slice(start, end + 1)) as ClaudeAnswerShape;

  // Validate the model output shape before trusting it: slugs must be strings,
  // and each must resolve to a real catalog entry.
  const slugs = Array.isArray(parsed.slugs)
    ? parsed.slugs.filter((s): s is string => typeof s === "string")
    : [];
  const results = slugs
    .map((slug) => getBySlug(slug))
    .filter((d): d is NonNullable<typeof d> => Boolean(d));

  return {
    query,
    interpretation: parsed.interpretation || "Interpreted by Claude.",
    answer: parsed.answer || `Found ${results.length} matching discoveries.`,
    results,
    source: "claude",
  };
}
